package md

import (
	"reflect"
	"testing"
)

func TestTrimsTrailingWhitespace(t *testing.T) {
	in := []string{"hello   ", "  indented\t", "", "keep"}
	want := []string{"hello", "  indented", "", "keep"}
	if got := Clean(in); !reflect.DeepEqual(got, want) {
		t.Fatalf("Clean = %q, want %q", got, want)
	}
}

func TestKeepsCodeBlocksVerbatim(t *testing.T) {
	in := []string{"text  ", "```", "code   ", "\tmore\t", "```", "after  "}
	want := []string{"text", "```", "code   ", "\tmore\t", "```", "after"}
	if got := Clean(in); !reflect.DeepEqual(got, want) {
		t.Fatalf("Clean = %q, want %q", got, want)
	}
}

func TestNeverTouchesLeadingWhitespace(t *testing.T) {
	in := []string{"    four  ", "\tone tab  "}
	want := []string{"    four", "\tone tab"}
	if got := Clean(in); !reflect.DeepEqual(got, want) {
		t.Fatalf("Clean = %q, want %q", got, want)
	}
}

