package md

import (
	"reflect"
	"testing"
)

func TestHiddenFenceCases(t *testing.T) {
	cases := []struct {
		name       string
		in, want   []string
	}{
		{
			"language tag",
			[]string{"```go  ", "x  ", "```  ", "y  "},
			[]string{"```go  ", "x  ", "```  ", "y"},
		},
		{
			"unterminated fence runs to the end",
			[]string{"a  ", "```", "b  ", "c  "},
			[]string{"a", "```", "b  ", "c  "},
		},
		{
			"indented fence still opens a block",
			[]string{"  ```", "z  ", "  ```", "w  "},
			[]string{"  ```", "z  ", "  ```", "w"},
		},
		{
			"two blocks",
			[]string{"```", "a  ", "```", "b  ", "```", "c  ", "```", "d  "},
			[]string{"```", "a  ", "```", "b", "```", "c  ", "```", "d"},
		},
		{
			"whitespace-only lines outside a block",
			[]string{"\t\t", "   "},
			[]string{"", ""},
		},
	}
	for _, c := range cases {
		if got := Clean(c.in); !reflect.DeepEqual(got, c.want) {
			t.Errorf("%s: Clean(%q) = %q, want %q", c.name, c.in, got, c.want)
		}
	}
	if got := Clean(nil); len(got) != 0 {
		t.Errorf("Clean(nil) = %q", got)
	}
}
